def encode(rows):
    data=[]
    for row in rows:
        p=[int(c) if c != "." else 0 for c in row]
        data.extend([sum((v&1)<<(7-i) for i,v in enumerate(p)),sum(((v>>1)&1)<<(7-i) for i,v in enumerate(p))])
    return data
